BEGIN;
CREATE SCHEMA IF NOT EXISTS erp_core;
SET LOCAL search_path TO erp_core;
CREATE TABLE IF NOT EXISTS workspace_settings (id TEXT PRIMARY KEY, data_json TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision > 0), updated BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS funnels (id TEXT PRIMARY KEY, data_json TEXT NOT NULL, revision INTEGER NOT NULL CHECK (revision > 0), position INTEGER NOT NULL, updated BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, funnel_id TEXT NOT NULL REFERENCES funnels(id), stage TEXT NOT NULL, data_json TEXT NOT NULL, details_json TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('open','progress','resolved')), revision INTEGER NOT NULL CHECK (revision > 0), created BIGINT NOT NULL, updated BIGINT NOT NULL, archived_at BIGINT);
CREATE INDEX IF NOT EXISTS leads_active_updated ON leads(archived_at,updated);
CREATE TABLE IF NOT EXISTS lead_notes (id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), actor TEXT NOT NULL, author_name TEXT NOT NULL, text TEXT NOT NULL, attachment_ids_json TEXT NOT NULL, created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS lead_notes_lead_created ON lead_notes(lead_id,created);
CREATE TABLE IF NOT EXISTS lead_attachments (id TEXT PRIMARY KEY, lead_id TEXT NOT NULL REFERENCES leads(id), name TEXT NOT NULL, size BIGINT NOT NULL CHECK (size > 0 AND size <= 3145728), mime_type TEXT NOT NULL, created BIGINT NOT NULL, duration REAL, content BYTEA NOT NULL);
CREATE INDEX IF NOT EXISTS lead_attachments_lead ON lead_attachments(lead_id,created);
CREATE TABLE IF NOT EXISTS records (id TEXT PRIMARY KEY, resource TEXT NOT NULL CHECK (resource IN ('agenda','orcamentos','pedidos','catalogo','producao','materiais','movimentacoes','financeiro')), data_json TEXT NOT NULL, lead_id TEXT NOT NULL DEFAULT '', parent_id TEXT NOT NULL DEFAULT '', revision INTEGER NOT NULL CHECK (revision > 0), created BIGINT NOT NULL, updated BIGINT NOT NULL, archived_at BIGINT);
CREATE INDEX IF NOT EXISTS records_resource_active ON records(resource,archived_at,created);
CREATE INDEX IF NOT EXISTS records_parent ON records(parent_id);
CREATE INDEX IF NOT EXISTS records_lead ON records(lead_id);
CREATE TABLE IF NOT EXISTS erp_audit (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, resource TEXT NOT NULL, record_id TEXT NOT NULL, created BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS erp_audit_created ON erp_audit(created);
ALTER TABLE workspace_settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE funnels ENABLE ROW LEVEL SECURITY;
ALTER TABLE leads ENABLE ROW LEVEL SECURITY;
ALTER TABLE lead_notes ENABLE ROW LEVEL SECURITY;
ALTER TABLE lead_attachments ENABLE ROW LEVEL SECURITY;
ALTER TABLE records ENABLE ROW LEVEL SECURITY;
ALTER TABLE erp_audit ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON SCHEMA erp_core FROM PUBLIC,anon,authenticated;
REVOKE ALL ON ALL TABLES IN SCHEMA erp_core FROM PUBLIC,anon,authenticated;
COMMIT;
